import _io

def newline(d) -> str:
    try:
        n = d.newlines
        if n is None or isinstance(n, str):
            return repr(n)
        return "multiple"
    except NotImplementedError:
        return "multiple"

pieces = ["", "a", "\r", "\n", "\r\n", "é\r", "\r😀"]
for translate in [False, True]:
    for final in [False, True]:
        for a in pieces:
            for b in pieces:
                d = _io.IncrementalNewlineDecoder(None, translate)
                x = d.decode(a)
                pending = d.getstate()
                y = d.decode(b, final)
                print(translate,final,repr(a),repr(b),repr(x),pending,repr(y),d.getstate(),newline(d))
                d.reset()
                d.setstate((b"",3))
                print("reset",repr(d.decode(b,True)),d.getstate(),newline(d))

